mapper.select:
        select 

        from STL_CAPACCT_INFO

        	1=1 

				and ACCT_NAME like concat('%',concat(#{acctName,jdbcType=VARCHAR},'%'))


				and BUSI_ACCT_NO = #{busiAcctNo,jdbcType=VARCHAR}


				and LARGE_PAYNO = #{largePayno,jdbcType=VARCHAR}


				and CCY = #{ccy,jdbcType=VARCHAR}


		order by BUSI_ACCT_NO desc

    	select sum(count) from(
		 select count(*) count from MST_COUNTER_ACCT T1 ,STL_CAPACCT_INFO T2 
		 	where T1.ACCT_NO=T2.ACCT_NO 
		 		and T1.CCY=T2.CCY 
		 		and T2.ACCT_NO = #{acctNo,jdbcType=VARCHAR} 
		 		and T2.CCY = #{ccy,jdbcType=VARCHAR}
		 union all select count(*) count from STL_FIN_PRODUCT_ACCT T3 ,STL_CAPACCT_INFO T4 
		 	where T3.ACCT_NO=T4.ACCT_NO 
		 		and T3.CCY=T4.CCY 
		 		and T4.ACCT_NO = #{acctNo,jdbcType=VARCHAR} 
		 		and T4.CCY = #{ccy,jdbcType=VARCHAR}
		 union all select count(*) count from PTL_CAPACCT_INFO T5 ,STL_CAPACCT_INFO T6 
		 	where T5.ACCT_NO=T6.ACCT_NO 
		 		and T5.CCY=T6.CCY 
		 		and T6.ACCT_NO = #{acctNo,jdbcType=VARCHAR}
		 		and T6.CCY = #{ccy,jdbcType=VARCHAR}
		)

mapper.delete:
    	delete STL_CAPACCT_INFO sci where 1=1  
				and sci.BUSI_ACCT_NO = #{busiAcctNo,jdbcType=VARCHAR}		
				and sci.LARGE_PAYNO = #{largePayno,jdbcType=VARCHAR}
				and sci.CCY = #{ccy,jdbcType=VARCHAR}

mapper.select:
    	select mca.counter_id counterId,mca.acct_no acctNo,mca.is_open isOpen from MST_COUNTER_ACCT mca 
				where mca.ACCT_NO = #{acctNo,jdbcType=VARCHAR} 
				and mca.CCY= #{ccy,jdbcType=VARCHAR}
				and mca.ACCT_TYPE = #{acctType,jdbcType=VARCHAR}

    	select count(*)
          from STL_CAPACCT_INFO s
		 	where s.BUSI_ACCT_NO = #{busiAcctNo,jdbcType=VARCHAR}

   		select mca.acct_no acctNo,mca.is_open isOpen,mca.ACCT_TYPE acctType,mca.ccy ccy 
   			from MST_COUNTER_ACCT mca 
			where mca.counter_id = #{counterId,jdbcType=VARCHAR}

   		select 

        from STL_CAPACCT_INFO

        	1=1 

				and ACCT_NO = #{acctNo,jdbcType=VARCHAR}


				and LARGE_PAYNO = #{largePayno,jdbcType=VARCHAR}


				and CCY = #{ccy,jdbcType=VARCHAR}


		order by BUSI_ACCT_NO desc
